#include <bits/stdc++.h>
using namespace std;

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    auto startTime = chrono::steady_clock::now();
    auto elapsed = [&]() -> double {
        return chrono::duration<double>(chrono::steady_clock::now()-startTime).count();
    };

    int N;
    cin >> N;
    vector<double> cx(N), cy(N);
    for(int i=0;i<N;i++) cin >> cx[i] >> cy[i];

    vector<bool> is_prime(N, false);
    {
        vector<bool> sieve(N, true);
        if(N>0) sieve[0]=false;
        if(N>1) sieve[1]=false;
        for(int i=2;(long long)i*i<N;i++)
            if(sieve[i])
                for(int j=i*i;j<N;j+=i) sieve[j]=false;
        for(int i=0;i<N;i++) is_prime[i]=sieve[i];
    }

    auto ddist = [&](int a, int b) -> double {
        double dx=cx[a]-cx[b], dy=cy[a]-cy[b];
        return sqrt(dx*dx+dy*dy);
    };

    // mult for step s (1-indexed), source city src
    auto mult = [&](int s, int src) -> double {
        return (s%10==0 && !is_prime[src]) ? 1.1 : 1.0;
    };

    auto tourCost = [&](const vector<int>& t) -> double {
        double cost=0;
        for(int s=1;s<=N;s++){
            cost += ddist(t[s-1],t[s]) * mult(s, t[s-1]);
        }
        return cost;
    };

    // Build initial tour using nearest neighbor with spatial hashing
    // For large N, use a grid-based approach
    vector<int> tour(N+1);
    {
        // Use a grid for nearest neighbor queries
        double minx=*min_element(cx.begin(),cx.end());
        double maxx=*max_element(cx.begin(),cx.end());
        double miny=*min_element(cy.begin(),cy.end());
        double maxy=*max_element(cy.begin(),cy.end());

        int gridSize = max(1, (int)sqrt((double)N / 4.0));
        double cellW = (maxx-minx)/gridSize + 1e-9;
        double cellH = (maxy-miny)/gridSize + 1e-9;
        if(cellW < 1e-12) cellW = 1.0;
        if(cellH < 1e-12) cellH = 1.0;

        vector<vector<int>> grid(gridSize*gridSize);
        auto getCell = [&](int id) -> int {
            int gx = min(gridSize-1, (int)((cx[id]-minx)/cellW));
            int gy = min(gridSize-1, (int)((cy[id]-miny)/cellH));
            return gy*gridSize+gx;
        };

        vector<bool> visited(N, false);
        for(int i=0;i<N;i++) grid[getCell(i)].push_back(i);

        tour[0]=0;
        visited[0]=true;
        // Remove 0 from its grid cell
        {
            int c=getCell(0);
            auto &v=grid[c];
            v.erase(find(v.begin(),v.end(),0));
        }

        for(int step=1;step<N;step++){
            int last=tour[step-1];
            int gx0=min(gridSize-1,(int)((cx[last]-minx)/cellW));
            int gy0=min(gridSize-1,(int)((cy[last]-miny)/cellH));

            int best=-1; double bestD=1e30;
            // Search expanding rings
            for(int rad=0;rad<gridSize*2 && best==-1 || rad<=1;rad++){
                // Check if minimum possible distance in ring > bestD
                if(best!=-1){
                    double minPossible = max(0.0, (double)(rad-1)) * min(cellW, cellH);
                    if(minPossible > bestD*1.5) break;
                }
                for(int dx=-rad;dx<=rad;dx++){
                    for(int dy=-rad;dy<=rad;dy++){
                        if(abs(dx)!=rad && abs(dy)!=rad) continue;
                        int gx=gx0+dx, gy=gy0+dy;
                        if(gx<0||gx>=gridSize||gy<0||gy>=gridSize) continue;
                        auto &v=grid[gy*gridSize+gx];
                        for(int id : v){
                            if(!visited[id]){
                                double d=ddist(last,id);
                                if(d<bestD){bestD=d;best=id;}
                            }
                        }
                    }
                }
            }
            tour[step]=best;
            visited[best]=true;
            {
                int c=getCell(best);
                auto &v=grid[c];
                v.erase(find(v.begin(),v.end(),best));
            }
        }
        tour[N]=0;
    }

    double curCost = tourCost(tour);

    // pos[city] = index in tour
    vector<int> pos(N);
    auto buildPos = [&](){
        for(int i=0;i<=N;i++) if(i<N) pos[tour[i]]=i;
        // handle tour[N]=0 separately
    };
    buildPos();

    // Penalty-aware swap of tour[i] and tour[j]
    auto trySwap = [&](int i, int j) -> double {
        if(i==j) return 0;
        if(i==0||i==N||j==0||j==N) return 0;

        // Compute old cost of affected edges
        double oldC=0, newC=0;
        // Affected steps: i, i+1, j, j+1 (if abs(i-j)>1)
        // If adjacent, steps i, i+1, i+2
        vector<int> steps;
        if(abs(i-j)==1){
            int lo=min(i,j);
            steps={lo, lo+1, lo+2};
        } else {
            steps={i, i+1, j, j+1};
        }

        for(int s : steps){
            if(s<1||s>N) continue;
            oldC += ddist(tour[s-1],tour[s]) * mult(s, tour[s-1]);
        }
        swap(tour[i], tour[j]);
        for(int s : steps){
            if(s<1||s>N) continue;
            newC += ddist(tour[s-1],tour[s]) * mult(s, tour[s-1]);
        }
        double delta = newC - oldC;
        if(delta < -1e-10){
            pos[tour[i]]=i; pos[tour[j]]=j;
            curCost += delta;
            return delta;
        }
        swap(tour[i], tour[j]);
        return 0.0;
    };

    // Strategic: swap primes into penalty positions
    // Penalty positions: indices where step = 10,20,30... => tour[9],tour[19],...
    // At step s=10k, source is tour[s-1]=tour[10k-1]. We want tour[10k-1] to be prime.
    // So penalty indices are 9,19,29,... (0-indexed in tour)

    while(elapsed() < 1.8){
        bool imp = false;
        // Try swapping non-prime at penalty pos with nearby prime
        for(int p=9; p<N; p+=10){
            if(is_prime[tour[p]]) continue;
            // Find nearest prime in tour to swap
            double bestDelta=0; int bestJ=-1;
            for(int delta=-200;delta<=200;delta++){
                int j=p+delta;
                if(j<1||j>=N||j==p) continue;
                if(!is_prime[tour[j]]) continue;
                if(j%10==9) continue; // don't steal from another penalty pos
                swap(tour[p],tour[j]);
                // quick eval
                double oldC2=0,newC2=0;
                vector<int> ss;
                if(abs(p-j)==1){int lo=min(p,j);ss={lo,lo+1,lo+2};}
                else ss={p,p+1,j,j+1};
                swap(tour[p],tour[j]);
                for(int s:ss){if(s>=1&&s<=N) oldC2+=ddist(tour[s-1],tour[s])*mult(s,tour[s-1]);}
                swap(tour[p],tour[j]);
                for(int s:ss){if(s>=1&&s<=N) newC2+=ddist(tour[s-1],tour[s])*mult(s,tour[s-1]);}
                swap(tour[p],tour[j]);
                if(newC2-oldC2<bestDelta){bestDelta=newC2-oldC2;bestJ=j;}
            }
            if(bestJ>=0){
                trySwap(p,bestJ);
                imp=true;
            }
        }

        // General 2-opt with limited segment length
        for(int i=1;i<N-1&&elapsed()<1.8;i++){
            for(int j=i+1;j<min(i+50,N)&&j<N;j++){
                int len=j-i+1;
                double oldSeg=0,newSeg=0;
                for(int s=i;s<=min(j+1,N);s++) oldSeg+=ddist(tour[s-1],tour[s])*mult(s,tour[s-1]);
                reverse(tour.begin()+i,tour.begin()+j+1);
                for(int s=i;s<=min(j+1,N);s++) newSeg+=ddist(tour[s-1],tour[s])*mult(s,tour[s-1]);
                if(newSeg<oldSeg-1e-10){
                    curCost+=newSeg-oldSeg;
                    buildPos();
                    imp=true;
                } else {
                    reverse(tour.begin()+i,tour.begin()+j+1);
                }
            }
        }
        if(!imp) break;
    }

    cout << N+1 << "\n";
    for(int i=0;i<=N;i++) cout << tour[i] << "\n";
}
